/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
void rsr_state_disarm(void)
{  
  if((RSR_CUR_TIME >= RSR_DISARM_TO_GWR_TIMEOUT) &&  cmd_q_insert (INPUT_GWR | INPUT_ON, RSR_CMD_INSERT_TIMEOUT)) 
    {  
      if(TACHLESS && rsr_vars.ign)
	    {
		  rsr_vars.idle_mode = TRUE ;  
		}
	  rsr_set_state   (RSR_STATE_GWR) ;
    }
}


